SELECT 
FROM notification
WHERE receiver_id = #{receiverId}
  AND deleted = 0

  AND read_status = CASE WHEN #{read} = TRUE THEN 1 ELSE 0 END


  AND type = #{type}


  AND create_time >= #{createdFrom}


  AND create_time <= #{createdTo}

ORDER BY create_time DESC, id DESC

SELECT 
FROM notification
WHERE receiver_id = #{receiverId}
  AND deleted = 0
ORDER BY create_time DESC, id DESC
LIMIT #{limit}
